import { loadFont as loadBarlow } from "@remotion/google-fonts/BarlowCondensed";
import { loadFont as loadArchivo } from "@remotion/google-fonts/Archivo";
import { AbsoluteFill, Easing, Img, interpolate, OffthreadVideo, Sequence, staticFile, useCurrentFrame } from "remotion";

// Old Dog'z / OD Company, v2: cartões de motion em preto e branco se alternam com o making of em tela cheia.
// Cada palavra entra leve no instante em que é dita (tempos da locução + o respiro aberto entre os blocos, ver
// (arquivo do cliente) voz-v2-espacada.wav). Frases fracas em Archivo caixa baixa, frases fortes em bloco pesado.
// Fecha como a v1: a mão chega na lente, a tela desliga como TV de tubo e o logo assina no preto.
// Sem áudio aqui: voz, música e efeitos são mixados à parte (make_audio_v2.py + ffmpeg).

const { fontFamily: BLOCK } = loadBarlow("normal", { weights: ["800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: TEXT } = loadArchivo("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const CM2_FPS = 30;
const TAP = 23.0; // segundo em que a mão chega na lente
const OFF = TAP + 0.5;
const LOGO = OFF + 0.25;
export const CM2_FRAMES = Math.round((LOGO + 2.65) * CM2_FPS);
const WHITE = "#FFFFFF";
const BLACK = "#000000";
const PAPER = "#F4F3F0"; // branco dos cartões, um tom abaixo do branco puro do logo

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.4, ease = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: ease });

// ───────── vídeo do cliente ─────────
type Shot = { at: number; dur: number; from: number; rate?: number; file?: string };
const Shots: React.FC<{ t: number; shots: Shot[]; zoom?: number }> = ({ t, shots, zoom = 0.05 }) => (
  <>
    {shots.map(({ at, dur, from, rate = 1, file = "orig" }, i) =>
      t >= at && t < at + dur ? (
        <AbsoluteFill key={i} style={{ overflow: "hidden", background: BLACK }}>
          <Sequence from={Math.round(at * CM2_FPS)} layout="none">
            <OffthreadVideo src={staticFile(`camisas/${file}.mp4`)} muted trimBefore={Math.round(from * CM2_FPS)} playbackRate={rate} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${1 + zoom * ((t - at) / dur)})` }} />
          </Sequence>
        </AbsoluteFill>
      ) : null,
    )}
  </>
);

const FULL: Shot[] = [
  // abertura: três batidas rápidas do making of antes do primeiro cartão
  { at: 0, dur: 0.2, from: 21.75 },
  { at: 0.2, dur: 0.2, from: 13.6 },
  { at: 0.4, dur: 0.55, from: 4.5 },
  // "Tem coisa que o tempo não leva." / "O jeito de andar," / "o olhar de quem conhece o caminho."
  { at: 4.75, dur: 2.45, from: 4.37, rate: 0.87 },
  { at: 7.2, dur: 1.4, from: 22.77, rate: 0.85 },
  { at: 8.6, dur: 1.1, from: 13.47, rate: 0.9 },
  { at: 9.7, dur: 1.3, from: 24.97, rate: 0.8 },
  // "Mas quem conhece o caminho não fica parado."
  { at: 13.0, dur: 0.95, from: 18.67 },
  { at: 13.95, dur: 0.95, from: 12.43 },
  { at: 14.9, dur: 1.4, from: 21.6, rate: 0.8 },
  // o toque na lente (making.mp4 segura o último quadro)
  { at: 21.7, dur: OFF - 21.7, from: 30.2, file: "making" },
];

// ───────── texto ─────────
// [palavra, segundo do vídeo em que é dita]
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size: number; color: string; strong?: boolean }> = ({ t, words, size, color, strong }) => (
  <div style={{ display: "flex", justifyContent: "center", gap: `${size * (strong ? 0.2 : 0.24)}px`, whiteSpace: "nowrap", fontFamily: strong ? BLOCK : TEXT, fontWeight: strong ? 800 : 600, fontSize: size, lineHeight: strong ? 1 : 1.16, letterSpacing: strong ? "0.01em" : "-0.02em", color }}>
    {words.map(([w, at], i) => {
      const e = k(t, at - 0.06, strong ? 0.5 : 0.6);
      return (
        <span key={i} style={{ display: "inline-block", opacity: k(t, at - 0.06, 0.28, Easing.linear), transform: `translateY(${(1 - e) * size * 0.22}px)`, filter: `blur(${(1 - e) * 8}px)` }}>{w}</span>
      );
    })}
  </div>
);

// ───────── cartão ─────────
type Enter = "cut" | "up" | "down" | "left";
const Card: React.FC<{ t: number; at: number; end: number; bg: string; enter?: Enter; children: React.ReactNode }> = ({ t, at, end, bg, enter = "cut", children }) => {
  if (t < at || t >= end) return null;
  const p = enter === "cut" ? 1 : k(t, at, 0.45, IN_OUT);
  const r = (1 - p) * 100;
  const clip = enter === "up" ? `inset(${r}% 0 0 0)` : enter === "down" ? `inset(0 0 ${r}% 0)` : enter === "left" ? `inset(0 0 0 ${r}%)` : undefined;
  // câmera: aproxima devagar o cartão inteiro
  const push = 1 + 0.045 * ((t - at) / (end - at));
  return (
    <AbsoluteFill style={{ background: bg, clipPath: clip }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", transform: `scale(${push})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
const Rule: React.FC<{ t: number; at: number; color: string; width?: number }> = ({ t, at, color, width = 150 }) => (
  <div style={{ height: 4, width, background: color, transform: `scaleX(${k(t, at, 0.7, IN_OUT)})` }} />
);

export const CamisasV2: React.FC = () => {
  const t = useCurrentFrame() / CM2_FPS;

  // toque: a imagem cede, estoura e fecha numa linha, depois num ponto
  const press = k(t, TAP - 0.06, 0.08);
  const sy = interpolate(t, [TAP + 0.03, TAP + 0.2], [1, 0.0035], { ...cl, easing: Easing.bezier(0.6, 0, 0.9, 0.3) });
  const sx = interpolate(t, [TAP + 0.2, TAP + 0.4], [1, 0.006], { ...cl, easing: Easing.bezier(0.5, 0, 0.8, 0.4) });
  const burn = interpolate(t, [TAP, TAP + 0.2], [0, 1], cl);
  const dot = interpolate(t, [TAP + 0.36, TAP + 0.5], [1, 0], cl);
  const afterglow = interpolate(t, [TAP + 0.2, TAP + 0.32, OFF + 0.2], [0, 0.5, 0], cl);
  const logoIn = k(t, LOGO, 0.7);

  // "Nova fase / Novo olhar / Nova atitude": uma por vez, no mesmo lugar
  const TRIO: [string, number, number][] = [["Nova fase.", 16.05, 16.92], ["Novo olhar.", 17.02, 17.88], ["Nova atitude.", 17.98, 99]];

  return (
    <AbsoluteFill style={{ background: BLACK }}>
      {t < OFF ? (
        <AbsoluteFill style={{ transform: `scale(${sx * (1 - 0.03 * press)}, ${sy * (1 - 0.03 * press)})`, opacity: dot, overflow: "hidden" }}>
          <Shots t={t} shots={FULL} />

          {/* 1 · preto: "Não é só uma nova coleção." */}
          <Card t={t} at={0.45} end={2.95} bg={BLACK} enter="down">
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
              <Words t={t} size={112} color={WHITE} words={[["Não", 0.61], ["é", 0.79], ["só", 0.83], ["uma", 1.03]]} />
              <Words t={t} size={112} color={WHITE} words={[["nova", 1.31], ["coleção.", 1.57]]} />
              <div style={{ marginTop: 46 }}><Rule t={t} at={0.75} color={WHITE} /></div>
            </div>
          </Card>

          {/* 2 · branco: janela do vídeo + "É um novo conceito." */}
          <Card t={t} at={2.5} end={4.75} bg={PAPER} enter="up">
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
              <div style={{ position: "relative", width: 620, height: 800, overflow: "hidden", clipPath: `inset(${(1 - k(t, 2.7, 0.6, IN_OUT)) * 100}% 0 0 0)` }}>
                <Shots t={t} zoom={0.1} shots={[{ at: 2.5, dur: 1.2, from: 30.0, rate: 0.9 }, { at: 3.7, dur: 1.05, from: 28.97, rate: 0.9 }]} />
              </div>
              <div style={{ marginTop: 70, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
                <Words t={t} size={104} color={BLACK} words={[["É", 3.05], ["um", 3.15], ["novo", 3.29]]} />
                <Words t={t} size={104} color={BLACK} words={[["conceito.", 3.55]]} />
              </div>
            </div>
          </Card>

          {/* 3 · branco: "A ESSÊNCIA PERMANECE." */}
          <Card t={t} at={10.5} end={13.0} bg={PAPER} enter="left">
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
              <Words t={t} size={186} color={BLACK} strong words={[["A", 10.95], ["ESSÊNCIA", 11.05]]} />
              <Words t={t} size={186} color={BLACK} strong words={[["PERMANECE.", 11.69]]} />
              <Img src={staticFile("camisas/logo-preto.png")} style={{ width: 300, marginTop: 56, opacity: k(t, 12.1, 0.5, Easing.linear), transform: `translateY(${(1 - k(t, 12.1, 0.6)) * 24}px)` }} />
            </div>
          </Card>

          {/* 4 · preto: três palavras, uma por vez */}
          <Card t={t} at={15.8} end={19.75} bg={BLACK} enter="down">
            <div style={{ position: "relative", width: 840, height: 150 }}>
              {TRIO.map(([text, at, out], i) => (
                <div key={i} style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", opacity: 1 - k(t, out, 0.1, Easing.linear) }}>
                  <Words t={t} size={124} color={WHITE} words={[[text, at]]} />
                </div>
              ))}
            </div>
            <div style={{ display: "flex", gap: 14, marginTop: 56 }}>
              {TRIO.map(([, at], i) => (
                <div key={i} style={{ width: 64, height: 4, background: "rgba(255,255,255,0.22)" }}>
                  <div style={{ width: "100%", height: "100%", background: WHITE, transformOrigin: "0 50%", transform: `scaleX(${k(t, at, 0.85, IN_OUT)})` }} />
                </div>
              ))}
            </div>
          </Card>

          {/* 5 · branco: "o jogo" */}
          <Card t={t} at={19.3} end={20.7} bg={PAPER} enter="up">
            <Words t={t} size={150} color={BLACK} words={[["o", 19.82], ["jogo", 19.98]]} />
          </Card>

          {/* 6 · preto: "MUDA." */}
          <Card t={t} at={20.7} end={21.7} bg={BLACK}>
            <div style={{ fontFamily: BLOCK, fontWeight: 800, fontSize: 372, lineHeight: 1, letterSpacing: "0.01em", color: WHITE, transform: `scale(${1.16 - 0.16 * k(t, 20.7, 0.4)})`, opacity: k(t, 20.7, 0.08, Easing.linear) }}>MUDA.</div>
          </Card>

          <AbsoluteFill style={{ background: WHITE, opacity: burn }} />
        </AbsoluteFill>
      ) : null}

      {/* brilho que o tubo deixa no centro depois de apagar */}
      <AbsoluteFill style={{ background: "radial-gradient(ellipse 46% 5% at 50% 50%, rgba(255,255,255,0.55), rgba(255,255,255,0) 100%)", opacity: afterglow }} />

      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", opacity: k(t, LOGO, 0.45) }}>
        <Img src={staticFile("camisas/logo-branco.png")} style={{ width: 780, transform: `scale(${0.9 + 0.08 * logoIn + 0.012 * (t - LOGO)})` }} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { CM2_FPS, CM2_FRAMES, CamisasV2 } from "./CamisasV2";

const Root: React.FC = () => (
  <>
    <Composition id="CamisasV2" component={CamisasV2} durationInFrames={CM2_FRAMES} fps={CM2_FPS} width={1080} height={1920} />
  </>
);
registerRoot(Root);
